               </properties>
          </persistence-unit>
      </persistence>

3. Tạo lớp DAO: StudentDAO.java
     Lớp DAO là nơi trung gian giúp chúng ta thao tác với CSDL (thêm, sửa, xóa, tìm
kiếm).
      import jakarta.persistence.*;
      import java.util.List;
      public class StudentDAO {
          private EntityManagerFactory emf =
      Persistence.createEntityManagerFactory("my-pu");
          public void addStudent(Student s) {
              EntityManager em = emf.createEntityManager();
              em.getTransaction().begin();
              em.persist(s); // Thêm mới sinh viên
              em.getTransaction().commit();
              em.close();
          }
          public void updateStudent(Student s) {

                                       -57-
                EntityManager em = emf.createEntityManager();
                em.getTransaction().begin();
                em.merge(s); // Cập nhật sinh viên
                em.getTransaction().commit();
                em.close();
           }
           public void deleteStudent(Long id) {
               EntityManager em = emf.createEntityManager();
               em.getTransaction().begin();
               Student s = em.find(Student.class, id);
               if (s != null) {
                   em.remove(s); // Xóa sinh viên
               }
               em.getTransaction().commit();
               em.close();
           }
           public Student findStudent(Long id) {
               EntityManager em = emf.createEntityManager();
               Student s = em.find(Student.class, id); // Tìm sinh viên
       theo ID
               em.close();
               return s;
           }
           public List<Student> getAllStudents() {
               EntityManager em = emf.createEntityManager();
               String jpql = "SELECT s FROM Student s";
               List<Student> list = em.createQuery(jpql,
       Student.class).getResultList(); // Lấy toàn bộ sinh viên
               em.close();
               return list;
           }
       }
Giải thích:
   •   EntityManagerFactory: tạo ra các đối tượng EntityManager.
   •   EntityManager: dùng để thao tác với dữ liệu (thêm, sửa, xóa, tìm).
   •   persist(): dùng để lưu đối tượng mới.
   •   merge(): dùng để cập nhật đối tượng đã tồn tại (trạng thái detached).
   •   find(): tìm theo ID.
   •   remove(): xóa đối tượng khỏi DB.
   •   createQuery(): dùng JPQL để truy vấn.
4. Gọi DAO từ servlet

                                          -58-
       @WebServlet("/students")
       public class StudentServlet extends HttpServlet {
            private StudentDAO studentDAO = new StudentDAO();

           protected void doGet(HttpServletRequest req,
       HttpServletResponse resp) throws ServletException, IOException {
                 List<Student> students = studentDAO.getAll();
               req.setAttribute("students", students);
       req.getRequestDispatcher("/student.jsp").forward(req, resp);
            }
       }
